<template><section><h1>내 소비 로그</h1><div class="grid"><ExpenseCard v-for="log in logs" :key="log.id" :log="log" @like="like" @delete="remove"/></div><p v-if="!logs.length" class="muted">아직 작성한 소비 로그가 없습니다.</p></section></template>
<script setup>import { onMounted, ref } from 'vue'; import api from '@/api/axios'; import ExpenseCard from '@/components/ExpenseCard.vue'; const logs=ref([]); const load=async()=>{logs.value=(await api.get('/api/v1/expenses/logs/')).data}; const like=async(log)=>{await api.post(`/api/v1/expenses/logs/${log.id}/like/`); await load()}; const remove=async(log)=>{if(confirm('삭제할까요?')){await api.delete(`/api/v1/expenses/logs/${log.id}/`); await load()}}; onMounted(load)</script>
